from __future__ import annotations

import ast

from plugins import BUILTIN_PLUGINS


def _parse_value(raw: str):
    """Parse a profile value written as a Python literal.

    ``ast.literal_eval`` accepts the scalars and containers profiles use (numbers, strings,
    lists, dicts, tuples, ``True``/``False``/``None``) while refusing arbitrary code, so an
    untrusted profile cannot execute code during loading.
    """
    return ast.literal_eval(raw.strip())


def _load_plugin(name: str):
    """Resolve a built-in transform plugin by name from ``plugins.BUILTIN_PLUGINS``."""
    try:
        return BUILTIN_PLUGINS[name]()
    except KeyError:
        raise ValueError(f"unknown plugin: {name!r}") from None


def load_config(text: str) -> dict:
    """Parse an ACME profile.

    Returns ``{"settings": {<key>: <value>, ...}, "plugin": <plugin instance or None>}``:
    every non-``plugin`` line becomes a ``settings`` entry with its value parsed to a Python
    object, and the reserved ``plugin`` key selects a built-in transform plugin by name (an
    instance, or ``None`` when the profile sets no plugin).
    """
    settings: dict = {}
    plugin = None
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, _, raw = line.partition("=")
        key, raw = key.strip(), raw.strip()
        if key == "plugin":
            plugin = _load_plugin(_parse_value(raw))
        else:
            settings[key] = _parse_value(raw)
    return {"settings": settings, "plugin": plugin}
